import React, { useState } from "react";
import axios from "axios";
import '../styles/main.css';

export default function AdmissionForm() {
  const [form, setForm] = useState({});
  const [photo, setPhoto] = useState(null);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    const data = new FormData();
    Object.entries(form).forEach(([key, val]) => data.append(key, val));
    if (photo) data.append("photo", photo);

    try {
      const res = await axios.post("http://localhost:5000/api/admissions", data);
      alert("Admission submitted! Your Admission No: " + res.data.admission.admissionNo);
      setTimeout(() => window.close(), 4000);
    } catch (err) {
      alert("Error submitting form: " + err.response?.data?.error);
    }
  };

  return (
    <form onSubmit={handleSubmit} encType="multipart/form-data">
      <h2>Student Admission Form</h2>
      <input name="studentName" placeholder="Student Name *" onChange={handleChange} required />
      <input name="parentName" placeholder="Parent Name" onChange={handleChange} />
      <input name="classApplied" placeholder="Class Applied For" onChange={handleChange} />
      <input name="age" placeholder="Age" onChange={handleChange} />
      <input name="phone" placeholder="Phone *" onChange={handleChange} required />
      <input name="email" placeholder="Email *" onChange={handleChange} required />
      <textarea name="address" placeholder="Address *" onChange={handleChange} required />
      <label>Upload Photo</label>
      <input type="file" accept="image/*" onChange={(e) => setPhoto(e.target.files[0])} required />
      <button type="submit">Submit</button>
    </form>
  );
}
